<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {answerCardExercise,fetchKnowledgeCardAttachment,fetchKnowledgeCardFrequency,fetchKnowledgeCards,generateCardExercises,submitCardExerciseReview,updateKnowledgeCardState,type CardExercise,type Frequency,type KnowledgeCard} from '../../api/student/knowledgeCards'
import ScientificText from '../../components/question/ScientificText.vue'
import AnswerDisplay from '../../components/question/AnswerDisplay.vue'
import StudentAiLearningPanel from '../../components/student/StudentAiLearningPanel.vue'
const cards=ref<KnowledgeCard[]>([]),selected=ref<KnowledgeCard>(),frequency=ref<Frequency[]>([]),loading=ref(false),imageSources=ref<Record<number,string>>({})
const exerciseVisible=ref(false),generating=ref(false),exercises=ref<CardExercise[]>([]),answers=reactive<Record<number,unknown>>({})
const filters=reactive({subjectId:undefined as number|undefined,knowledgePointId:undefined as number|undefined,type:'',favorite:undefined as boolean|undefined,mastery:''})
const exerciseForm=reactive({questionType:'SINGLE_CHOICE',difficulty:3,variationMode:'SCENARIO_TRANSFER',count:1})
const types=[['POINT','考点'],['FORMULA','公式'],['CHEMICAL_EQUATION','方程式'],['SECONDARY_CONCLUSION','二级结论'],['INSTRUMENT','实验器具'],['MNEMONIC','口诀'],['TABLE','表格'],['NOTE','笔记']]
const subjects=computed(()=>[...new Map(cards.value.map(c=>[c.subjectId,{id:c.subjectId,name:c.subjectName}])).values()]),points=computed(()=>[...new Map(cards.value.flatMap(c=>c.knowledgePoints).map(p=>[p.id,p])).values()])
async function load(){loading.value=true;try{cards.value=await fetchKnowledgeCards({subjectId:filters.subjectId,knowledgePointId:filters.knowledgePointId,type:filters.type||undefined,favorite:filters.favorite,mastery:filters.mastery||undefined})}catch{ElMessage.error('知识卡片加载失败。')}finally{loading.value=false}}
function clearImages(){Object.values(imageSources.value).forEach(URL.revokeObjectURL);imageSources.value={}}
async function open(card:KnowledgeCard){clearImages();selected.value=card;frequency.value=await fetchKnowledgeCardFrequency(card.id);for(const item of card.attachments)try{imageSources.value[item.id]=URL.createObjectURL(await fetchKnowledgeCardAttachment(card.id,item.id))}catch{ElMessage.warning(`${item.name} 暂不可读取。`)}}
async function state(card:KnowledgeCard,favorite=card.favorite,mastery=card.mastery){selected.value=await updateKnowledgeCardState(card.id,{favorite,mastery});cards.value=cards.value.map(c=>c.id===card.id?selected.value!:c)}
async function generateExercises(){if(!selected.value)return;generating.value=true;try{exercises.value=await generateCardExercises(selected.value.id,exerciseForm);exercises.value.forEach(e=>answers[e.id]=e.questionType==='MULTIPLE_CHOICE'||e.questionType==='FILL_BLANK'?[]:'');exerciseVisible.value=true}catch(error){ElMessage.error((error as {message?:string}).message||'卡片练习生成失败。')}finally{generating.value=false}}
function fill(id:number,index:number,value:string){const values=[...((answers[id] as string[])||[])];values[index]=value;answers[id]=values}
async function answerExercise(item:CardExercise){try{const updated=await answerCardExercise(item.id,answers[item.id]);exercises.value=exercises.value.map(e=>e.id===item.id?updated:e)}catch(error){ElMessage.error((error as {message?:string}).message||'答案提交失败。')}}
async function submitReview(item:CardExercise){try{const updated=await submitCardExerciseReview(item.id);exercises.value=exercises.value.map(e=>e.id===item.id?updated:e);ElMessage.success('候选题保持 PENDING，已提交人工审核。')}catch(error){ElMessage.error((error as {message?:string}).message||'提交审核失败。')}}
onMounted(load);onBeforeUnmount(clearImages)
</script>
<template><main class="card-library"><header><p>REVIEWED SCIENCE CARDS</p><h1>知识卡片与公式口诀</h1><span>所有可见内容均已人工审核；“近年高频”只来自满足来源条件的真题统计。</span></header><section class="filters"><el-select v-model="filters.subjectId" clearable placeholder="学科"><el-option v-for="s in subjects" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="filters.knowledgePointId" clearable filterable placeholder="知识点"><el-option v-for="p in points" :key="p.id" :label="p.path" :value="p.id"/></el-select><el-select v-model="filters.type" clearable placeholder="卡片类型"><el-option v-for="t in types" :key="t[0]" :label="t[1]" :value="t[0]"/></el-select><el-select v-model="filters.mastery" clearable placeholder="掌握状态"><el-option label="学习中" value="LEARNING"/><el-option label="已掌握" value="MASTERED"/></el-select><el-button type="primary" @click="load">筛选</el-button></section><section v-loading="loading" class="card-grid"><article v-for="card in cards" :key="card.id" tabindex="0" @click="open(card)" @keydown.enter="open(card)"><div><el-tag effect="plain">{{types.find(t=>t[0]===card.type)?.[1]}}</el-tag><span>{{card.subjectName}}</span></div><h2>{{card.title}}</h2><ScientificText :content="card.content"/><small>{{card.knowledgePoints.map(p=>p.path).join(' · ')}}</small><footer><el-button link @click.stop="state(card,!card.favorite,card.mastery)">{{card.favorite?'取消收藏':'收藏'}}</el-button><el-button link @click.stop="state(card,card.favorite,card.mastery==='MASTERED'?'LEARNING':'MASTERED')">{{card.mastery==='MASTERED'?'改为学习中':'标记已掌握'}}</el-button></footer></article><el-empty v-if="!cards.length" description="暂无符合条件的已审核卡片"/></section><el-drawer v-model="selected" size="min(720px,100%)" title="知识卡片详情"><template v-if="selected"><h2>{{selected.title}}</h2><p>{{selected.subjectName}} · {{selected.knowledgePoints.map(p=>p.path).join('；')}}</p><ScientificText :content="selected.content"/><section v-if="selected.latex"><h3>公式 / 科学表达</h3><ScientificText :content="selected.latex"/></section><section v-if="selected.applicableConditions"><h3>适用条件</h3><ScientificText :content="selected.applicableConditions"/></section><section v-if="selected.derivation"><h3>含义与推导</h3><ScientificText :content="selected.derivation"/></section><section v-if="selected.example"><h3>简单例子</h3><ScientificText :content="selected.example"/></section><section v-if="selected.commonMistake"><h3>常见误区</h3><ScientificText :content="selected.commonMistake"/></section><section v-if="selected.mnemonic"><h3>记忆口诀</h3><ScientificText :content="selected.mnemonic"/></section><figure v-for="image in selected.attachments" :key="image.id"><img v-if="imageSources[image.id]" :src="imageSources[image.id]" :alt="image.name"><figcaption>{{image.name}}</figcaption></figure><section class="frequency"><article v-for="f in frequency" :key="f.window"><strong>{{f.window}}</strong><span>{{f.occurrences}} 题 · {{f.paperCount}} 份试卷</span><p v-if="f.sampleNotice">{{f.sampleNotice}}</p></article></section><p class="source">来源：<a v-if="selected.sourceUrl" :href="selected.sourceUrl" target="_blank" rel="noopener noreferrer">{{selected.sourceName}}</a><span v-else>{{selected.sourceName||'项目自编总结'}}</span> · {{selected.rightsStatus}}</p><StudentAiLearningPanel :knowledge-card-id="selected.id"/><section class="exercise-builder"><h3>生成练习</h3><el-select v-model="exerciseForm.questionType"><el-option label="单选" value="SINGLE_CHOICE"/><el-option label="多选" value="MULTIPLE_CHOICE"/><el-option label="填空" value="FILL_BLANK"/></el-select><el-input-number v-model="exerciseForm.difficulty" :min="1" :max="5"/><el-input-number v-model="exerciseForm.count" :min="1" :max="3"/><el-select v-model="exerciseForm.variationMode"><el-option label="情境迁移" value="SCENARIO_TRANSFER"/><el-option label="条件重组" value="CONDITION_RECOMBINATION"/><el-option label="表达转换" value="REPRESENTATION_SWITCH"/><el-option label="多步骤扩展" value="MULTI_STEP_EXTENSION"/><el-option label="干扰项重构" value="DISTRACTOR_REDESIGN"/><el-option label="综合变式" value="COMBINED"/></el-select><el-button type="primary" :loading="generating" @click="generateExercises">生成练习</el-button></section><el-alert title="复用统一 Candidate Schema、Parser 与新颖度；确定性判分，题库提交仍为 PENDING。" type="info" :closable="false"/></template></el-drawer><el-dialog v-model="exerciseVisible" title="卡片临时练习" width="min(760px,calc(100vw - 24px))"><article v-for="item in exercises" :key="item.id" class="exercise"><el-tag>难度 {{item.difficulty}}</el-tag><ScientificText :content="item.stem"/><el-radio-group v-if="item.questionType==='SINGLE_CHOICE'" v-model="answers[item.id]" :disabled="item.status!=='READY'"><el-radio v-for="o in item.options" :key="o.label" :value="o.label">{{o.label}}. {{o.content}}</el-radio></el-radio-group><el-checkbox-group v-else-if="item.questionType==='MULTIPLE_CHOICE'" v-model="answers[item.id] as string[]" :disabled="item.status!=='READY'"><el-checkbox v-for="o in item.options" :key="o.label" :value="o.label">{{o.label}}. {{o.content}}</el-checkbox></el-checkbox-group><div v-else class="blank-list"><el-input v-for="index in item.answerSlots" :key="index" :model-value="(answers[item.id] as string[]||[])[index-1]" :disabled="item.status!=='READY'" :placeholder="`第 ${index} 空`" @update:model-value="fill(item.id,index-1,$event)"/></div><el-button v-if="item.status==='READY'" type="primary" @click="answerExercise(item)">确定性判分</el-button><section v-else><el-tag :type="item.correct?'success':'danger'">{{item.correct?'正确':'错误'}}</el-tag><AnswerDisplay :question-type="item.questionType" :value="item.correctAnswer" :options="item.options"/><h4>AI 生成解析，仅用于本次练习</h4><ScientificText :content="item.aiAnalysis||''"/><el-button v-if="item.status==='ANSWERED'" @click="submitReview(item)">提交人工审核</el-button><el-tag v-else type="warning">PENDING · 等待人工审核</el-tag></section></article></el-dialog></main></template>
<style scoped>.card-library{max-width:1280px;margin:auto;padding:28px}.card-library>header{padding:28px;border-radius:24px;background:linear-gradient(135deg,#e7fbff,#f6f1ff)}header p{letter-spacing:.16em;color:#177b8f}.filters,.exercise-builder{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.filters .el-select{width:190px}.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}.card-grid>article{display:flex;flex-direction:column;gap:10px;padding:20px;border:1px solid var(--el-border-color-lighter);border-radius:18px;background:white;box-shadow:0 10px 30px rgba(23,72,88,.07);cursor:pointer}.card-grid>article:focus-visible{outline:3px solid var(--el-color-primary-light-5)}.card-grid article>div,.card-grid footer{display:flex;justify-content:space-between}.card-grid h2{margin:0}.card-grid small,.source{color:var(--el-text-color-secondary)}figure img{max-width:100%;border-radius:14px}.frequency{display:grid;grid-template-columns:1fr 1fr;gap:12px}.frequency article{display:grid;padding:12px;border-radius:12px;background:var(--el-fill-color-light)}.exercise{display:grid;gap:12px;padding:16px;border-bottom:1px solid var(--el-border-color-lighter)}@media(max-width:640px){.card-library{padding:14px}.filters .el-select{width:100%}.frequency{grid-template-columns:1fr}}</style>
